          {/capture}
          {=og_include('compose/Stack.latte', ['gap' => '2', 'class' => og_s(og_cnv([(og_t(og_eq($v_item, 'card')) ? 'rounded bg-card inset-ring inset-ring-border p-6' : 'py-4'), (og_t(og_eq(og_get($v_f, ['id']), $v_active)) ? 'inset-ring inset-ring-foreground' : '')])), 'attrs' => og_attrs(['data-testid', 'item', 'aria-current', (og_t(og_eq(og_get($v_f, ['id']), $v_active)) ? 'true' : null)]), 'children' => (string) $c_4])|noescape}
